var __index = {"config":{"lang":["en","zh"],"separator":"[\\s\\u200b\\u3000\\-\u3001\u3002\uff0c\uff0e\uff1f\uff01\uff1b]+","pipeline":["stemmer"],"fields":{"title":{"boost":1000.0},"text":{"boost":1.0},"tags":{"boost":1000000.0}}},"docs":[{"location":"en/index.html","title":"Home","text":"\u4ee5\u53ef\u7231\u5f62\u8c61\u5c55\u793a\u6309\u952e\u52a8\u4f5c\uff0c\u70b9\u7f00\u4f60\u7684\u684c\u9762\u6216\u76f4\u64ad\u95f4 <p>CatTuber\u4e00\u6b3e\u5e26\u6709\u89d2\u8272\u5f62\u8c61\u7684\u8f93\u5165\u5c55\u793a\u8f6f\u4ef6\uff0c        \u89d2\u8272\u4f1a\u8ddf\u968f\u4f60\u7684\u8bbe\u5907\u8f93\u5165\u505a\u51fa\u5bf9\u5e94\u7684\u52a8\u4f5c\u3002</p> <p>\u652f\u6301\u952e\u76d8\u3001\u9f20\u6807\u3001\u6e38\u620f\u624b\u67c4\u3001\u9762\u90e8\u6355\u6349\u7b49\u591a\u79cd\u5f62\u5f0f\u7684\u52a8\u4f5c\u8f93\u5165.       \u652f\u6301\u952e\u76d8\u3001\u9f20\u6807\u3001\u6e38\u620f\u624b\u67c4\u3001\u9762\u90e8\u6355\u6349\u7b49\u591a\u79cd\u5f62\u5f0f\u7684\u52a8\u4f5c\u8f93\u5165\uff0c </p> Steam \u591a\u5143\u8f93\u5165 <p>\u652f\u6301\u591a\u79cd\u54c1\u724c\u7684\u6e38\u620f\u624b\u67c4\uff0c\u652f\u6301\u5bf9\u65e0\u6cd5\u8bc6\u522b\u7684\u624b\u67c4\u8fdb\u884c\u6620\u5c04\u3002</p> \u53cc\u673a\u652f\u6301 <p>\u652f\u6301\u5c06\u8bbe\u5907\u8f93\u5165\u8f6c\u53d1\u5230\u63a8\u6d41\u7535\u8111,\u76f4\u64ad\u652f\u6301\u65e0\u6b7b\u89d2</p> \u5916\u7f6e\u9762\u6355 <p>\u652f\u6301\u63a5\u6536\u6765\u81ea\u5916\u90e8\u8bbe\u5907\u7684\u9762\u90e8\u6570\u636e,\u7535\u8111\u538b\u529bDown Down</p> Bongo Cat Mver\u517c\u5bb9 <p>Bongo Cat Mver\u672a\u63d0\u4f9b\u7684\u4fbf\u5229\u529f\u80fd,\u5728\u8fd9\u91cc\u90fd\u53ef\u4ee5\u4eab\u53d7\u5230</p>"},{"location":"en/ChangeLog/ChangeLog.html","title":"\u66f4\u65b0\u65e5\u5fd7","text":""},{"location":"en/ChangeLog/ChangeLog.html#100","title":"1.0.0 \u5168\u65b0\u7684\u5f00\u59cb","text":"<p>2027\u5e741\u67081\u65e5</p> <ul> <li>\u65b0\u7684UI\u754c\u9762</li> <li>\u65b0\u7684\u573a\u666f\u7ba1\u7406\u7cfb\u7edf</li> <li>\u65b0\u7684\u6a21\u578b\u673a\u5236</li> <li>\u65b0\u7684\u6e32\u67d3\u5e95\u5c42</li> </ul>"},{"location":"en/wiki/WikiHome.html","title":"Welcome to MkDocsaaaa","text":"<p>For full documentation visit mkdocs.org.</p>"},{"location":"en/wiki/WikiHome.html#commands","title":"Commands","text":"<ul> <li><code>mkdocs new [dir-name]</code> - Create a new project.</li> <li><code>mkdocs serve</code> - Start the live-reloading docs server.</li> <li><code>mkdocs build</code> - Build the documentation site.</li> <li><code>mkdocs -h</code> - Print help message and exit.</li> </ul>"},{"location":"en/wiki/WikiHome.html#project-layout","title":"Project layout","text":"<pre><code>mkdocs.yml    # The configuration file.\ndocs/\n    index.md  # The documentation homepage.\n    ...       # Other markdown pages, images and other files.\n</code></pre>"},{"location":"en/wiki/Tutorial/Broadcast.html","title":"\u4f7f\u7528CatTuber\u8fdb\u884c\u76f4\u64ad\u6216\u5f55\u5236\u7684\u65b9\u6cd5&amp;\u5e38\u89c1\u95ee\u9898","text":""},{"location":"en/wiki/Tutorial/Broadcast.html#_1","title":"\u5de5\u5177\u7684\u9009\u62e9","text":"<p>\u4efb\u4f55\u60c5\u51b5\u4e0b\u90fd\u63a8\u8350\u4f7f\u7528OBS\u8fdb\u884c\u76f4\u64ad\u6216\u5f55\u5236\u3002</p> <p>\u9700\u8981\u5728\u4e0d\u4f7f\u7528OBS\u7684\u60c5\u51b5\u4e0b\u4e0e\u6e38\u620f\u4e00\u8d77\u5f55\u5236CatTuber\u7684\u753b\u9762\u7684\u8bdd\uff0c\u9700\u8981\u4f60\u7684\u5de5\u5177\u6709\u4ee5\u4e0b\u80fd\u529b\uff1a</p> <p>\u753b\u9762\u7f16\u6392: \u5728\u975e\u76f4\u63a5\u5f55\u5236\u5c4f\u5e55\u7684\u60c5\u51b5\u4e0b\uff0c\u9700\u8981\u80fd\u7f16\u8f91\u753b\u9762\u5185\u5bb9\u4ee5\u5728\u6e38\u620f\u753b\u9762\u4e4b\u4e0a\u6dfb\u52a0\u6765\u81ea\u5176\u4ed6\u7a97\u53e3\u7684\u5185\u5bb9\u3002</p> <p>\u753b\u9762\u6355\u83b7: - \u4ee5\u6e38\u620f\u7684\u65b9\u5f0f\u6355\u83b7\u5176\u4ed6\u7a97\u53e3\uff08\u6700\u4f18\u63a8\u8350\uff09 - \u4ee5\u7a97\u53e3\u7684\u65b9\u5f0f\u6355\u83b7\u5176\u4ed6\u7a97\u53e3 - \u865a\u62df\u6444\u50cf\u5934\uff08\u6d89\u53ca\u5927\u91cfGPU\u5230CPU\u548cCPU\u5230CPU\u7684\u5185\u5b58\u62f7\u8d1d\uff0c\u6027\u80fd\u6700\u5dee\uff09</p>"},{"location":"en/wiki/Tutorial/Broadcast.html#_2","title":"\u80cc\u666f\u53bb\u9664","text":"<p>\u5982\u679c\u662f\u4ee5\u6e38\u620f\u6355\u83b7\u83b7\u53d6CatTuber\u753b\u9762\uff0c\u5728\u6e38\u620f\u6355\u83b7\u7684\u8bbe\u7f6e\u9875\u9762\u52fe\u9009 \"\u5141\u8bb8\u7a97\u53e3\u900f\u660e\".</p> <p>\u5bf9\u4e8e\u5176\u4ed6\u65e0\u6cd5\u83b7\u53d6\u900f\u660e\u901a\u9053\u7684\u6355\u83b7\uff0c\u53ef\u5148\u8bbe\u7f6eCatTuber\u7a97\u53e3\u80cc\u666f\u989c\u8272\u4e3a\u5408\u9002\u989c\u8272\uff0c\u7136\u540e\u4ee5\u53bb\u9664\u7279\u5b9a\u989c\u8272\u7684\u65b9\u5f0f\u53bb\u9664\u80cc\u666f.</p> <p>\u5bf9\u4e8eOBS,\u8bbe\u7f6e\u65b9\u6cd5\u4e3a\u6dfb\u52a0\u6ee4\u955c\u3002</p>"},{"location":"en/wiki/Tutorial/Broadcast.html#_3","title":"\u6027\u80fd","text":"<p>\u4f7f\u7528\u975e\u900f\u660e\u7a97\u53e3\u7684CatTuber\u914d\u5408\u6e38\u620f\u6355\u83b7\u65f6\u80fd\u83b7\u5f97\u6700\u4f73\u6027\u80fd\u3002</p> <p>\u7a97\u53e3\u6355\u83b7\u6b21\u4e4b\uff0c\u56e0\u4e3a\u591a\u4e86\u4e00\u6b21CPU\u5230CPU\u7684\u590d\u5236\u3001\u591a\u4e86\u4e00\u6b21\u80cc\u666f\u900f\u660e\u5904\u7406\u3002</p> <p>\u865a\u62df\u6444\u50cf\u5934\u6700\u6b21\uff0c\u8fd9\u662f\u6d89\u53ca\u5185\u5b58\u590d\u5236\u6700\u591a\u7684\u65b9\u6848\uff08CatTuber\u5185\u90e8\u9700\u8981\u6bcf\u5e27\u5c06GPU\u4e2d\u7684\u753b\u9762\u8f93\u51fa\u5230CPU\u5185\u5b58\u7136\u540e\u9001\u5165\u865a\u62df\u6444\u50cf\u5934\uff0cOBS\u4e5f\u8981\u5148\u83b7\u53d6\u865a\u62df\u6444\u50cf\u5934\u4e2d\u7684\u753b\u9762\u5230OBS\u81ea\u5df1\u7684\u5185\u5b58\u4e2d\uff0c\u800c\u4e0d\u662f\u50cf\u6e38\u620f\u6355\u83b7\u90a3\u6837\u76f4\u63a5\u83b7\u53d6\u663e\u5361\u5185\u90e8\u753b\u9762\u5730\u5740\uff09\u3002</p> <p>\u5bf9\u4e8eCatTuber\u81ea\u8eab\uff0cCatTuber\u5728\u6700\u5c0f\u5316\u6216\u9690\u85cf\u65f6\u4e5f\u80fd\u88abOBS\u6355\u83b7\u3002 \u4f7f\u7528\u900f\u660e\u7a97\u53e3\u4e14\u4e0d\u6700\u5c0f\u5316\u6216\u9690\u85cfCatTuber\u7a97\u53e3\u65f6\uff0c\u4f1a\u5728\u64cd\u4f5c\u7cfb\u7edf\u5904\u7406\u7a97\u53e3\u900f\u660e\u6548\u679c\u65f6\u6d88\u8017\u6389\u5c0f\u90e8\u5206\u6027\u80fd\u3002</p>"},{"location":"en/wiki/Tutorial/Broadcast.html#_4","title":"\u65e0\u6cd5\u6355\u83b7\u753b\u9762\u65f6\u7684\u5e94\u5bf9","text":""},{"location":"en/wiki/Tutorial/Broadcast.html#_5","title":"\u7531\u6743\u9650\u5bfc\u81f4\u7684\u65e0\u6cd5\u6355\u83b7","text":"<p>CatTuber\u548cOBS\uff08\u6216\u4f60\u7684\u76f4\u64ad\u5f55\u5236\u5de5\u5177\uff09\u9700\u8981\u81f3\u5c11\u62e5\u6709\u4e0e\u6e38\u620f\u76f8\u540c\u7684\u6743\u9650\uff0c\u56e0\u4e3aCatTuber\u6743\u9650\u4f4e\u4e8e\u6e38\u620f\u65f6\uff0cCatTuber\u5c06\u65e0\u6cd5\u6b63\u5e38\u83b7\u53d6\u6e38\u620f\u7a97\u53e3\u4e2d\u7684\u8bbe\u5907\u8f93\u5165\uff0cOBS\u6743\u9650\u4f4e\u4e8e\u6e38\u620f\u6216CatTuber\u65f6\uff0cOBS\u5c06\u65e0\u6cd5\u83b7\u53d6\u753b\u9762\u3002</p> <p>CatTuber\u53ef\u5728\u8f6f\u4ef6\u8bbe\u7f6e\u9875\u4e2d\u52fe\u9009\u662f\u5426\u9700\u8981\u7ba1\u7406\u5458\u6743\u9650\u3002</p> <p>OBS\u5982\u679c\u4e0b\u8f7d\u81ea\u5176\u5b98\u7f51\uff0c\u90a3\u4e48\u5b83\u901a\u5e38\u4f1a\u5728\u542f\u52a8\u65f6\u81ea\u52a8\u83b7\u53d6\u7ba1\u7406\u5458\u6743\u9650\uff1b\u800c\u5982\u679c\u4e0b\u8f7d\u81eaSteam\uff0cOBS\u5c06\u4e0d\u4f1a\u81ea\u52a8\u83b7\u53d6\u7ba1\u7406\u5458\u6743\u9650\u3002\u89e3\u51b3\u65b9\u6848\u662f\u5bfb\u627e\u5230OBS\u672c\u5730\u7a0b\u5e8f\u6587\u4ef6\uff0c\u901a\u8fc7\u5bf9\u5176\u53f3\u952e\u2192\u5c5e\u6027\u2192\u517c\u5bb9\u6027\u2192\u4ee5\u7ba1\u7406\u5458\u8eab\u4efd\u8fd0\u884c\u6b64\u7a0b\u5e8f\u6765\u8bbe\u7f6e\u4e0b\u8f7d\u81eaSteam\u7684OBS\u7684\u7ba1\u7406\u5458\u6743\u9650\uff0c\u7136\u540e\u901a\u8fc7\u76f4\u63a5\u8fd0\u884c\u7a0b\u5e8f\u6216\u5176\u5feb\u6377\u65b9\u5f0f\u7684\u5f62\u5f0f\u8fd0\u884cOBS\uff0c\u800c\u4e0d\u662f\u901a\u8fc7Steam\u6216Steam\u521b\u5efa\u7684\u5feb\u6377\u65b9\u5f0f\u8fd0\u884cOBS\u3002</p>"},{"location":"en/wiki/Tutorial/Broadcast.html#_6","title":"\u7531\u663e\u5361\u8bbe\u7f6e\u5bfc\u81f4\u7684\u65e0\u6cd5\u6355\u83b7","text":"<p>OBS\u9700\u8981\u4e0eCatTuber\u6216\u6e38\u620f\u4f7f\u7528\u540c\u4e00\u5f20\u663e\u5361\u624d\u80fd\u83b7\u53d6\u753b\u9762\uff0c\u56e0\u6b64\u5bf9\u4e8e\u6709\u591a\u5f20\u663e\u5361\u7684\u7535\u8111\uff08\u901a\u5e38\u662f\u4e00\u5f20\u72ec\u7acb\u663e\u5361+\u4e00\u4e2a\u6765\u81eaCPU\u81ea\u5e26\u7684\u663e\u5361\uff09\uff0c\u8bf7\u5c06OBS\u3001CatTuber\u3001\u6e38\u620f\u90fd\u8bbe\u7f6e\u4e3a\u4f7f\u7528\u7535\u8111\u4e0a\u7684\u9ad8\u6027\u80fd\u663e\u5361\u3002</p>"},{"location":"en/wiki/Tutorial/Broadcast.html#_7","title":"\u753b\u9762\u5f02\u5e38","text":""},{"location":"en/wiki/Tutorial/Broadcast.html#_8","title":"\u9884\u671f\u4e4b\u5916\u7684\u8f6e\u5ed3","text":"<p>\u901a\u5e38\u662fCatTuber\u4e0e\u76f4\u64ad\u8f6f\u4ef6\u5bf9\u753b\u9762\u8fb9\u7f18\u534a\u900f\u660e\u50cf\u7d20\u7684\u5904\u7406\u95ee\u9898\u3002</p> <p>\u5982\u679c\u91c7\u7528\u975e\u6e38\u620f\u6355\u83b7+\u5173\u952e\u8272\u53bb\u80cc\u666f\u7684\u65b9\u5f0f\uff0c\u8bf7\u5728\u4f60\u6240\u4f7f\u7528\u7684\u5de5\u5177\u7684\u5173\u952e\u8272\u53bb\u9664\u80cc\u666f\u76f8\u5173\u7684\u5730\u65b9\u5bfb\u627e\"\u989c\u8272\u5bb9\u5dee\"\u7684\u8bbe\u7f6e\u9879\u3002</p> <p>\u5982\u679c\u91c7\u7528\u900f\u660e\u7684\u6e38\u620f\u6355\u83b7\uff0c\u53ef\u4ee5\u5c1d\u8bd5\u8c03\u6574OBS\u4e2d\u6e38\u620f\u6355\u83b7\u8bbe\u7f6e\u9879\u4e2d\u7684\"\u9884\u4e58\"\u3001\u5c1d\u8bd5\u5c06CatTuber\u80cc\u666f\u8272\u8c03\u6574\u4e3a\u7eaf\u9ed1\u6216\u7eaf\u767d\u3001\u5c1d\u8bd5\u8c03\u6574CatTuber\u8bbe\u7f6e\u9879\u4e2d\u7684\"\u9884\u4e58\"\uff0c\u76f4\u5230CatTuber\u5728OBS\u4e2d\u65e0\u663e\u773c\u8f6e\u5ed3\u3002</p>"},{"location":"en/wiki/Tutorial/Tutorial.html","title":"TSETaaa","text":""},{"location":"en/wiki/Tutorial/Tutorial.html#test","title":"\u76ee\u5f55test","text":""}]}